def _reference_analysis(
        self, address: RepositoryResourceAddress
    ) -> PythonDeclarationReferenceAnalysis | None:
        """Share canonical scoped static analysis with relationship/map views."""
        interpretations = tuple(
            i
            for root in ("src", ".")
            for i in interpret_python_module_resources(
                self.snapshot,
                module_root=PythonModuleRoot(root),
                resource_addresses=tuple(
                    a
                    for a in self.addresses
                    if a.value.startswith("src/") == (root == "src")
                ),
            ).interpretations
        )
        try:
            return derive_python_declaration_references(
                self.snapshot,
                resource_address=address,
                module_universe=define_python_module_interpretation_universe(
                    repository_id=self.repository.id,
                    interpretations=interpretations,
                ),
                source_interpretations=tuple(
                    i for i in interpretations if i.resource.address == address
                ),
            )
        except SyntaxError:
            return None

def __init__(self, tools: ContextTools) -> None:
        """Reuse existing admitted declarations and static reference derivation."""
        started = time.perf_counter()
        self.tools = tools
        declarations = {
            unit.declaration.identity: unit.declaration
            for view in tools.index.views
            for unit in view.units
            if unit.declaration is not None
        }.values()
        references = tuple(
            reference
            for address in tools.addresses
            if (analysis := tools._reference_analysis(address)) is not None
            for reference in analysis.references
        )
        self.view = build_repository_map_view(
            tools.snapshot,
            core=build_python_graph_view(
                tools.snapshot,
                projection=PythonGraphProjection.TYPED_CORE,
                functions=tuple(
                    d
                    for d in declarations
                    if isinstance(d, PythonFunctionDeclarationKnowledge)
                ),
                classes=tuple(
                    d
                    for d in declarations
                    if isinstance(d, PythonClassDeclarationKnowledge)
                ),
                methods=tuple(
                    d
                    for d in declarations
                    if isinstance(d, PythonMethodDeclarationKnowledge)
                ),
                references=references,
            ),
        )
        self.importance = calculate_repository_map_importance(
            tools.snapshot,
            view=self.view,
        )
        self.preparation_seconds = time.perf_counter() - started
        self.selections: dict[
            str,
            tuple[RepositoryMapDisclosureOption, RepositoryMapSymbol],
        ] = {}
